#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;

    explicit DSU(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    vector<int> price(K);
    for (int &p : price) cin >> p;

    vector<vector<pair<int, int>>> edgesByColor(K);
    for (int i = 0; i < M; ++i) {
        int u, v, t;
        cin >> u >> v >> t;
        --u;
        --v;
        --t;
        edgesByColor[t].push_back({u, v});
    }

    int A, B;
    cin >> A >> B;
    --A;
    --B;

    vector<vector<pair<int, int>>> graph(N);
    vector<int> seen(N, -1), localIndex(N);
    int stamp = 0;

    for (int color = 0; color < K; ++color) {
        const auto &edges = edgesByColor[color];
        if (edges.empty()) continue;

        ++stamp;
        vector<int> vertices;
        vertices.reserve(edges.size() * 2);

        for (auto [u, v] : edges) {
            if (seen[u] != stamp) {
                seen[u] = stamp;
                localIndex[u] = vertices.size();
                vertices.push_back(u);
            }
            if (seen[v] != stamp) {
                seen[v] = stamp;
                localIndex[v] = vertices.size();
                vertices.push_back(v);
            }
        }

        DSU dsu(vertices.size());
        for (auto [u, v] : edges) {
            dsu.unite(localIndex[u], localIndex[v]);
        }

        vector<int> componentNode(vertices.size(), -1);
        for (int i = 0; i < (int)vertices.size(); ++i) {
            int root = dsu.find(i);
            if (componentNode[root] == -1) {
                componentNode[root] = graph.size();
                graph.emplace_back();
            }

            int station = vertices[i];
            int component = componentNode[root];
            graph[station].push_back({component, price[color]});
            graph[component].push_back({station, 0});
        }
    }

    const long long INF = LLONG_MAX / 4;
    vector<long long> dist(graph.size(), INF);
    priority_queue<pair<long long, int>,
                   vector<pair<long long, int>>,
                   greater<pair<long long, int>>> pq;

    dist[A] = 0;
    pq.push({0, A});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        if (u == B) break;

        for (auto [v, cost] : graph[u]) {
            if (dist[v] > d + cost) {
                dist[v] = d + cost;
                pq.push({dist[v], v});
            }
        }
    }

    cout << (dist[B] == INF ? -1 : dist[B]) << '\n';
    return 0;
}
